1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export interface QuoteStep {
23	  op: "quote";
24	  items: Item[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	
57	// One row per item type the office recognises. Base premium (what it costs to
58	// insure) and insurance value (what it is insured FOR) are independent numbers,
59	// but they are known for exactly the same set of types — so they belong in one
60	// table. Keeping them apart would leave two key sets that must agree with
61	// nothing enforcing it.
62	interface ItemSpec {
63	  basePremium: number;
64	  insuranceValue: number;
65	}
66	
67	const ITEM_SPECS = {
68	  sword: { basePremium: 100, insuranceValue: 1000 },
69	  amulet: { basePremium: 60, insuranceValue: 600 },
70	  staff: { basePremium: 80, insuranceValue: 800 },
71	  potion: { basePremium: 40, insuranceValue: 400 },
72	  rune: { basePremium: 25, insuranceValue: 250 },
73	  moonstone: { basePremium: 25, insuranceValue: 250 },
74	} as const satisfies Record<string, ItemSpec>;
75	
76	type KnownItemType = keyof typeof ITEM_SPECS;
77	
78	const isKnownItemType = (type: string): type is KnownItemType =>
79	  type in ITEM_SPECS;
80	
81	// The office insures only what its price list names. An unknown type has no
82	// premium and no insurance value, so there is nothing to quote — the whole
83	// scenario is rejected rather than priced at zero.
84	const specForItem = (item: Item): ItemSpec => {
85	  if (!isKnownItemType(item.type)) {
86	    throw new Error(`The MHPCO does not insure items of type ${item.type}`);
87	  }
88	  return ITEM_SPECS[item.type];
89	};
90	
91	const basePremiumForItem = (item: Item): number => specForItem(item).basePremium;
92	
93	const BLOCK_SIZE = 3;
94	
95	const BLOCK_BASE_PREMIUM = 60;
96	
97	const sum = (amounts: number[]): number =>
98	  amounts.reduce((total, amount) => total + amount, 0);
99	
100	// "Alike" means the same exact type, not merely the same family: two runes and
101	// a moonstone are three components but not three alike ones, so grouping them
102	// by type keeps them apart and denies them the block price.
103	const groupByType = (items: Item[]): Item[][] => {
104	  const groups = new Map<string, Item[]>();
105	  for (const item of items) {
106	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
107	  }
108	  return [...groups.values()];
109	};
110	
111	// A block is not carved out of a larger group: the block price applies only
112	// when the group consists of exactly three alike components (7 runes cost
113	// 7 × 25, not 60 + 60 + 25). Alikeness is guaranteed by the caller, which only
114	// ever passes a single group from groupByType.
115	const basePremiumForGroup = (group: Item[]): number =>
116	  group.length === BLOCK_SIZE
117	    ? BLOCK_BASE_PREMIUM
118	    : sum(group.map(basePremiumForItem));
119	
120	const basePremiumForItems = (items: Item[]): number =>
121	  sum(groupByType(items).map(basePremiumForGroup));
122	
123	const CURSE_SURCHARGE = 0.5;
124	
125	// Every modifier is an additive percentage of its OWN base — modifiers never
126	// compound with each other. Item-scoped modifiers take the affected item's base
127	// premium as their base; policy-scoped modifiers take the policy base premium
128	// (the sum of all item base premiums). So the total is always
129	// base + Σ (rate × that modifier's base), never a product of (1 + rate) factors.
130	const modifierAmount = (rate: number, base: number): number => rate * base;
131	
132	const ENCHANTMENT_SURCHARGE = 0.3;
133	
134	const ENCHANTMENT_SURCHARGE_LEVEL = 5;
135	
136	const isCursed = (item: Item): boolean => item.cursed === true;
137	
138	const attractsEnchantmentSurcharge = (item: Item): boolean =>
139	  (item.enchantment ?? 0) >= ENCHANTMENT_SURCHARGE_LEVEL;
140	
141	interface ItemModifier {
142	  rate: number;
143	  appliesTo: (item: Item) => boolean;
144	}
145	
146	// Each item-scoped modifier is a row: a rate and the condition under which it
147	// applies. The predicate names the modifier, so a row needs no separate label.
148	// Adding a modifier means adding a row, not a new branch.
149	const ITEM_MODIFIERS: ItemModifier[] = [
150	  { rate: CURSE_SURCHARGE, appliesTo: isCursed },
151	  { rate: ENCHANTMENT_SURCHARGE, appliesTo: attractsEnchantmentSurcharge },
152	];
153	
154	const itemModifierRates = (item: Item): number[] =>
155	  ITEM_MODIFIERS.filter((modifier) => modifier.appliesTo(item)).map(
156	    (modifier) => modifier.rate,
157	  );
158	
159	const LOYALTY_DISCOUNT = 0.2;
160	
161	const LOYALTY_THRESHOLD_YEARS = 2;
162	
163	const isLongStanding = (customer: Customer): boolean =>
164	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
165	
166	// Discounts are surcharges with the sign flipped: expressing one as a negative
167	// rate lets it flow through the same additive sum as every surcharge, with no
168	// separate subtraction step. Discount constants stay positive magnitudes and
169	// are negated here, at the point of use, so the direction is visible in the
170	// rate list rather than buried in a constant's sign.
171	const asDiscount = (rate: number): number => -rate;
172	
173	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
174	
175	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
176	
177	// Policy-scoped modifiers apply to the policy base premium. Unlike item
178	// modifiers they select on the customer and on the quote's position in the
179	// scenario rather than on an item.
180	//
181	// The initial-assessment surcharge applies to every quote: each item is treated
182	// as a first insurance regardless of customer history. The follow-up discount
183	// is what distinguishes a customer's later contracts.
184	const policyModifierRates = (
185	  customer: Customer,
186	  isFollowUpContract: boolean,
187	): number[] => [
188	  INITIAL_ASSESSMENT_SURCHARGE,
189	  ...(isLongStanding(customer) ? [asDiscount(LOYALTY_DISCOUNT)] : []),
190	  ...(isFollowUpContract ? [asDiscount(FOLLOW_UP_CONTRACT_DISCOUNT)] : []),
191	];
192	
193	const itemModifiersTotal = (items: Item[]): number =>
194	  sum(
195	    items.flatMap((item) =>
196	      itemModifierRates(item).map((rate) =>
197	        modifierAmount(rate, basePremiumForItem(item)),
198	      ),
199	    ),
200	  );
201	
202	const policyModifiersTotal = (
203	  policyBasePremium: number,
204	  customer: Customer,
205	  isFollowUpContract: boolean,
206	): number =>
207	  sum(
208	    policyModifierRates(customer, isFollowUpContract).map((rate) =>
209	      modifierAmount(rate, policyBasePremium),
210	    ),
211	  );
212	
213	// All amounts are rounded to whole G in the MHPCO's favour. For a premium —
214	// money flowing to the MHPCO — its favour is upwards. Payouts flow the other
215	// way and so round down, but no test drives payout ROUNDING yet (payouts
216	// themselves are computed and tested; they just land on whole numbers), so
217	// only the premium direction is named here.
218	const roundPremiumInMHPCOsFavour = (amount: number): number =>
219	  Math.ceil(amount);
220	
221	const quotePremium = (
222	  items: Item[],
223	  customer: Customer,
224	  isFollowUpContract: boolean,
225	): number => {
226	  const policyBasePremium = basePremiumForItems(items);
227	  return roundPremiumInMHPCOsFavour(
228	    policyBasePremium +
229	      itemModifiersTotal(items) +
230	      policyModifiersTotal(policyBasePremium, customer, isFollowUpContract) +
231	      PROCESSING_FEE,
232	  );
233	};
234	
235	const insuranceValueForItem = (item: Item): number =>
236	  specForItem(item).insuranceValue;
237	
238	// Deliberately NOT the shape of basePremiumForItems. Both aggregate a per-item
239	// figure from ITEM_SPECS, but the premium side groups by type first so a block
240	// of three alike components can be priced as one; this side never groups. Three
241	// runes cost 60 to insure and are insured for 3 × 250 = 750. The block is a
242	// discount on the price of cover, not a reduction of the cover bought.
243	//
244	// So the near-symmetry is a false friend: factoring the two into one traversal
245	// would read as tidier and would silently make blocks shrink the insurance sum.
246	// The repetition of `sum(items.map(...))` is the price of keeping them free to
247	// diverge, and is paid on purpose.
248	const insuranceSum = (items: Item[]): number =>
249	  sum(items.map(insuranceValueForItem));
250	
251	const CAP_MULTIPLE = 2;
252	
253	// The cap is twice the insurance sum — the value the items are insured FOR, so
254	// it is computed from the items alone and never from the premium. Curses,
255	// enchantments and loyalty change what a policy costs without changing what it
256	// covers (as do blocks — see insuranceSum). Naming the relation keeps that
257	// separation visible at the one place a policy is created.
258	const capForItems = (items: Item[]): number =>
259	  CAP_MULTIPLE * insuranceSum(items);
260	
261	const DEDUCTIBLE = 100;
262	
263	interface Policy {
264	  items: Item[];
265	  remainingCap: number;
266	}
267	
268	// Steps are not independent: a quote's premium depends on how many quotes came
269	// before it, and a claim draws down the cap of a policy an earlier quote
270	// created. So a step is a function from state to (result, next state), and the
271	// scenario is a fold over that — not a map, which would promise an independence
272	// the steps do not have.
273	//
274	// Policies are keyed by the index of the quote step that created them: a claim
275	// step names its policy by that zero-based index.
276	interface ScenarioState {
277	  quotesSoFar: number;
278	  policies: Map<number, Policy>;
279	}
280	
281	const INITIAL_STATE: ScenarioState = {
282	  quotesSoFar: 0,
283	  policies: new Map(),
284	};
285	
286	interface StepOutcome {
287	  result: StepResult;
288	  state: ScenarioState;
289	}
290	
291	// Both operations end by filing a policy under its quote's index — a claim
292	// re-files the same policy with a drawn-down cap. Naming that once keeps the
293	// Map out of the operations, so neither has to know how policies are stored.
294	const withPolicy = (
295	  state: ScenarioState,
296	  policyIndex: number,
297	  policy: Policy,
298	): ScenarioState => ({
299	  ...state,
300	  policies: new Map(state.policies).set(policyIndex, policy),
301	});
302	
303	const runQuote = (
304	  step: QuoteStep,
305	  customer: Customer,
306	  state: ScenarioState,
307	  stepIndex: number,
308	): StepOutcome => ({
309	  result: {
310	    premium: quotePremium(step.items, customer, state.quotesSoFar > 0),
311	  },
312	  state: withPolicy(
313	    { ...state, quotesSoFar: state.quotesSoFar + 1 },
314	    stepIndex,
315	    {
316	      items: step.items,
317	      remainingCap: capForItems(step.items),
318	    },
319	  ),
320	});
321	
322	const REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
323	
324	const REDUCED_REIMBURSEMENT_RATE = 0.5;
325	
326	const FULL_REIMBURSEMENT_RATE = 1;
327	
328	// Reads enchantment like the premium-side surcharge rule, but is a different
329	// rule with its own level: this one halves what a claim pays out, that one
330	// raises what a policy costs. Sharing a predicate would tie two levels that the
331	// spec lets move independently, so the shape is repeated deliberately.
332	const qualifiesForReducedReimbursement = (item: Item): boolean =>
333	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL;
334	
335	// The reimbursement rate is decided first, then one deductible comes off.
336	//
337	// The dragon-material clause is absent on purpose, not by oversight. It promises
338	// full reimbursement of the damage before the deductible — which is exactly what
339	// FULL_REIMBURSEMENT_RATE already gives every item that misses the reduced-rate
340	// clause. Where both clauses apply the spec awards it to the 50 % rule. Between
341	// them the two facts leave the clause with no input it can move: dragon material
342	// at enchantment 9 or 8 pays the same 400 as steel at those levels, and at
343	// enchantment 5 it pays the same 700 steel would. Writing it as its own branch
344	// would add a branch no test could ever tell from the default — a distinction
345	// the domain does not make.
346	const reimbursementRate = (item: Item): number =>
347	  qualifiesForReducedReimbursement(item)
348	    ? REDUCED_REIMBURSEMENT_RATE
349	    : FULL_REIMBURSEMENT_RATE;
350	
351	const payoutForDamage = (damage: Damage, item: Item): number =>
352	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
353	
354	// Returns AN insured item of the damaged type, not THE damaged one — a policy
355	// can cover two swords, so the type does not name a unique item. Two damage
356	// entries of the same type are both answered with the same first match.
357	//
358	// That is sound today because the answer is used solely to read payout
359	// attributes (the reimbursement rate), and the covered case — two damages
360	// against two swords — insures identical swords, which read the same either
361	// way. The deductible is charged per damage entry, not per matched item, so
362	// counting is unaffected too.
363	//
364	// One thing would break it, not yet under test: two swords with DIFFERENT
365	// attributes (say enchantment 3 and 9). Both damages would take the first
366	// sword's rate; the second should take its own. This lookup must then become a
367	// pairing that consumes what it matches. The honest name marks that spot.
368	//
369	// The `!` is a proof, not an assumption: rejectUnmatchedDamages runs first and
370	// throws unless every claimed type is covered at least as many times as it is
371	// named — so by the time this runs, a match exists for every damage entry. Both
372	// ways it could fail are covered by tests: claiming a type more often than it is
373	// insured, and claiming a type the policy does not cover at all.
374	const anInsuredItemOfDamagedType = (policy: Policy, damage: Damage): Item =>
375	  policy.items.find((item) => item.type === damage.itemType)!;
376	
377	// Counts how many times each value occurs. Deliberately typed on strings rather
378	// than on Item: the guard below tallies two different things (item types held
379	// and item types named by damages) and only their counts are ever compared, so
380	// the tally has no business knowing what the strings mean.
381	const tally = (values: string[]): Map<string, number> => {
382	  const counts = new Map<string, number>();
383	  for (const value of values) {
384	    counts.set(value, (counts.get(value) ?? 0) + 1);
385	  }
386	  return counts;
387	};
388	
389	// Every damage entry must claim an insured item of its own, so a type cannot be
390	// damaged more times than the policy covers it. One rule, two error cases the
391	// spec states separately: claiming a type more often than it is insured, and
392	// claiming a type the policy does not cover at all. The second is the first at
393	// zero — an uninsured type is covered 0 times against a claimed 1 — so both are
394	// caught by the same comparison rather than by a separate membership test.
395	//
396	// Checked before any payout is computed: the spec rejects the whole claim, not
397	// just the surplus entries.
398	const rejectUnmatchedDamages = (policy: Policy, incident: Incident): void => {
399	  const insured = tally(policy.items.map((item) => item.type));
400	  const claimed = tally(incident.damages.map((damage) => damage.itemType));
401	  for (const [type, claimedCount] of claimed) {
402	    const insuredCount = insured.get(type) ?? 0;
403	    if (claimedCount > insuredCount) {
404	      throw new Error(
405	        `Policy covers ${insuredCount} ${type}(s) but the claim names ${claimedCount}`,
406	      );
407	    }
408	  }
409	};
410	
411	// A damage is what an incident cost the owner, so it cannot be negative. Zero
412	// is left alone: the spec forbids only negative amounts, and a zero damage
413	// simply pays nothing once the deductible bites.
414	const isNegative = (damage: Damage): boolean => damage.amount < 0;
415	
416	const rejectNegativeDamages = (incident: Incident): void => {
417	  const negative = incident.damages.find(isNegative);
418	  if (negative) {
419	    throw new Error(
420	      `Damage to ${negative.itemType} is negative: ${negative.amount}`,
421	    );
422	  }
423	};
424	
425	// Both guards run before any payout is computed: the spec rejects the whole
426	// claim, not just the offending entries, so a valid entry alongside an invalid
427	// one must not be paid.
428	//
429	// They are two statements rather than a list of validations. Their signatures
430	// differ (only the first needs the policy), so a uniform list could hold them
431	// only by giving the second a parameter it ignores. And the order is not
432	// incidental: rejectUnmatchedDamages must come first because it is what makes
433	// the lookup in anInsuredItemOfDamagedType total — an obligation that reads as
434	// a sequenced line here but would vanish into array order in a list. The third
435	// validation the spec calls for (unknown item type) belongs to the quote path,
436	// so this pair is closed at two and has no growth to abstract over.
437	const payoutForIncident = (policy: Policy, incident: Incident): number => {
438	  rejectUnmatchedDamages(policy, incident);
439	  rejectNegativeDamages(incident);
440	  return sum(
441	    incident.damages.map((damage) =>
442	      payoutForDamage(damage, anInsuredItemOfDamagedType(policy, damage)),
443	    ),
444	  );
445	};
446	
447	// A policy's cap is a balance, not a per-claim limit: each claim spends part of
448	// it and the rest carries forward to the next claim against the same policy.
449	// Naming the draw-down separates what the cap DOES from how a claim is assembled
450	// — the one line in runClaim that was arithmetic rather than plumbing.
451	const drawDownCap = (remainingCap: number, payout: number): number =>
452	  remainingCap - payout;
453	
454	const runClaim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
455	  // A claim naming a policy that does not exist is a spec error case, but no
456	  // test drives it yet. The assertion stands in until one does — at which point
457	  // the missing case becomes the error branch rather than a crash.
458	  const policy = state.policies.get(step.policy)!;
459	  // The damage decides what the claim is worth; the cap decides what is left to
460	  // pay it with. Once the cap is spent the office pays what remains, not what
461	  // was asked.
462	  const payout = Math.min(
463	    payoutForIncident(policy, step.incident),
464	    policy.remainingCap,
465	  );
466	  const remainingCap = drawDownCap(policy.remainingCap, payout);
467	  return {
468	    result: { payout, remainingCap },
469	    state: withPolicy(state, step.policy, { ...policy, remainingCap }),
470	  };
471	};
472	
473	// Dispatch decides once what a step is; each operation then owns both its
474	// result and how it advances the state, so no caller has to re-test step.op to
475	// know what the step did.
476	const runStep = (
477	  step: Step,
478	  customer: Customer,
479	  state: ScenarioState,
480	  stepIndex: number,
481	): StepOutcome =>
482	  step.op === "quote"
483	    ? runQuote(step, customer, state, stepIndex)
484	    : runClaim(step, state);
485	
486	// The fold carries both halves of the outcome: the results accumulated so far
487	// and the state the next step will see. Threading the state explicitly (rather
488	// than recovering it from the last result) keeps the dependency between steps
489	// visible in the type.
490	interface ScenarioRun {
491	  results: StepResult[];
492	  state: ScenarioState;
493	}
494	
495	const INITIAL_RUN: ScenarioRun = { results: [], state: INITIAL_STATE };
496	
497	const appendStep =
498	  (customer: Customer) =>
499	  (run: ScenarioRun, step: Step, stepIndex: number): ScenarioRun => {
500	    const outcome = runStep(step, customer, run.state, stepIndex);
501	    return {
502	      results: [...run.results, outcome.result],
503	      state: outcome.state,
504	    };
505	  };
506	
507	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => ({
508	  results: steps.reduce(appendStep(customer), INITIAL_RUN).results,
509	});
